"""Dependency-free report with accessible SVG charts and local interactions."""
import json
from html import escape


def write_report(path, metrics, frame):
    data={"dates":frame.timestamp.astype(str).tolist(),"lines":[frame.equity.tolist(),frame.buy_hold_equity.tolist()],"probability":frame.p_up.tolist()}
    payload=json.dumps(data,allow_nan=False).replace('<','\\u003c')
    kind=metrics['source']['kind']
    html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>xgbitcoin · Research ledger</title>
<style>*{box-sizing:border-box}body{margin:0;background:#0b1018;color:#e8edf5;font:16px system-ui}main{max-width:1220px;margin:auto;padding:48px 32px}header{display:flex;justify-content:space-between;align-items:center}.brand{letter-spacing:.2em;font-size:13px;color:#8ca1b9}.badge{border:1px solid #354255;border-radius:30px;padding:9px 16px;color:#ffca74;font-size:12px}h1{font-size:clamp(36px,6vw,70px);font-weight:500;letter-spacing:-.05em;max-width:800px;margin-bottom:18px}p{color:#93a3b8;line-height:1.7;max-width:780px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:36px 0}.card,.chart{background:#111a26;border:1px solid #253447;border-radius:18px;padding:22px}.label{font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:#8295af}.value{font-size:30px;margin-top:9px}.chart header{margin-bottom:24px}.chart h2{font-size:20px;margin:0}.legend{display:flex;gap:10px}button{background:#192637;border:1px solid #35475d;color:#b6c7db;border-radius:24px;padding:9px 14px;cursor:pointer}button.active{color:#71f4c4;border-color:#409578}svg{width:100%;height:360px;display:block}#readout{min-height:28px;color:#71f4c4;font:13px monospace}.foot{display:grid;grid-template-columns:1fr 1fr;gap:36px;margin-top:34px;border-top:1px solid #253447;padding-top:24px}.foot h3{font-size:15px}@media(max-width:700px){main{padding:24px 16px}.grid{grid-template-columns:repeat(2,1fr)}.foot{grid-template-columns:1fr}.chart header{display:block}.legend{margin-top:16px}}
</style><main><header><div class="brand">XGBITCOIN / RESEARCH LAB</div><div class="badge">SOURCE_BADGE</div></header><h1>Observe the signal.<br>Account for the cost.</h1><p>A chronological holdout, a fixed trained model and a transparent long/cash ledger. Explore the outcome against buy-and-hold, with the same cost convention.</p><div class="grid">CARDS</div><section class="chart"><header><div><h2>Holdout equity</h2><p style="margin:6px 0;font-size:13px">Starts at1.0 · fees included · hover for observations</p></div><div class="legend"><button id="strategy" class="active" aria-pressed="true">● XGBoost signal</button><button id="baseline" class="active" aria-pressed="true">● Buy & hold</button></div></header><svg id="plot" viewBox="0 0 1100 360" role="img" aria-label="Chronological test equity curves"></svg><div id="readout" aria-live="polite">Move over the chart to inspect a held-out observation.</div></section><div class="foot"><div><h3>Research boundaries</h3><p>BOUNDARY</p></div><div><h3>Evaluation contract</h3><p>Split chronologically; one observation purged. Features lag a full bar. Fixed probability threshold0.55. The saved model was reloaded and predictions matched exactly. No test-set tuning.</p></div></div></main>
<script>const data=PAYLOAD;const svg=document.querySelector('#plot');const ns='http://www.w3.org/2000/svg';let visible=[true,true];function add(tag,attr,text){const e=document.createElementNS(ns,tag);Object.entries(attr).forEach(([k,v])=>e.setAttribute(k,v));if(text)e.textContent=text;svg.appendChild(e);return e}function draw(){svg.replaceChildren();let values=data.lines.flat(),lo=Math.min(1,...values),hi=Math.max(1,...values),pad=(hi-lo||.1)*.12;lo-=pad;hi+=pad;const x=i=>55+i/(data.dates.length-1)*1020,y=v=>320-(v-lo)/(hi-lo)*280;for(let k=0;k<5;k++){let v=lo+(hi-lo)*k/4;add('line',{x1:55,x2:1075,y1:y(v),y2:y(v),stroke:'#253447'});add('text',{x:5,y:y(v)+4,fill:'#8295af','font-size':12},v.toFixed(2))}data.lines.forEach((line,j)=>{if(visible[j])add('path',{d:line.map((v,i)=>(i?'L':'M')+x(i)+','+y(v)).join(' '),fill:'none',stroke:j?'#8b9ffc':'#71f4c4','stroke-width':2.5})});add('text',{x:55,y:348,fill:'#8295af','font-size':12},data.dates[0].slice(0,10));add('text',{x:975,y:348,fill:'#8295af','font-size':12},data.dates.at(-1).slice(0,10));}draw();['strategy','baseline'].forEach((id,j)=>document.getElementById(id).onclick=e=>{visible[j]=!visible[j];e.target.classList.toggle('active',visible[j]);e.target.setAttribute('aria-pressed',visible[j]);draw()});svg.onpointermove=e=>{const box=svg.getBoundingClientRect();const i=Math.max(0,Math.min(data.dates.length-1,Math.round(((e.clientX-box.left)/box.width*1100-55)/1020*(data.dates.length-1))));document.getElementById('readout').textContent=data.dates[i].slice(0,10)+' · signal '+data.lines[0][i].toFixed(4)+' · benchmark '+data.lines[1][i].toFixed(4)+' · P(up) '+data.probability[i].toFixed(3)};</script></html>'''
    cards=[('Train observations',metrics['train_rows']),('Holdout observations',metrics['test_rows']),('Test accuracy',f"{metrics['test_accuracy']:.1%}"),('Turnover fee',f"{metrics['fee_bps']:g}bps")]
    html=html.replace('CARDS',''.join(f'<div class="card"><div class="label">{escape(k)}</div><div class="value">{escape(str(v))}</div></div>' for k,v in cards))
    html=html.replace('SOURCE_BADGE',escape(kind.upper().replace('_',' '))).replace('BOUNDARY',escape('Seeded synthetic data are not BTC market history. '+metrics['execution_assumption'] if kind=='seeded_synthetic' else metrics['execution_assumption']))
    path.write_text(html.replace('PAYLOAD',payload))
